}","import React, { useState, useEffect, useCallback } from "react";
import {
 fetchDarkStores,
 fetchZoneForStore,
 fetchDeliveryPartners,
 submitComplaint,
 RefOption,
} from "./services/api";
import "./app.css";

const COMPLAINT_TYPES = [
 { value: "not_delivered", label: "Not Delivered" },
 { value: "late_delivery", label: "Late Delivery" },
 { value: "missing_items", label: "Missing Items" },
 { value: "damaged_items", label: "Damaged Items" },
 { value: "wrong_items", label: "Wrong Items" },
 { value: "quality_issue", label: "Quality Issue" },
];

interface SubmitResult {
 number?: string;
 sys_id?: string;
}

export default function App() {
 const [orderNumber, setOrderNumber] = useState("");
 const [orderValue, setOrderValue] = useState("");
 const [darkStore, setDarkStore] = useState("");
 const [deliveryZone, setDeliveryZone] = useState("");
 const [deliveryZoneLabel, setDeliveryZoneLabel] = useState("");
 const [deliveryPartner, setDeliveryPartner] = useState("");
 const [complaintType, setComplaintType] = useState("");
 const [shortDesc, setShortDesc] = useState("");
 const [description, setDescription] = useState("");

 const [darkStores, setDarkStores] = useState<RefOption[]>([]);
 const [partners, setPartners] = useState<RefOption[]>([]);
 const [loadingZone, setLoadingZone] = useState(false);
 const [loadingPartners, setLoadingPartners] = useState(false);

 const [submitting, setSubmitting] = useState(false);
 const [success, setSuccess] = useState<SubmitResult | null>(null);
 const [error, setError] = useState("");

 useEffect(() => {
 fetchDarkStores().then(setDarkStores).catch(console.error);
 }, []);

 const handleDarkStoreChange = useCallback(
 async (storeId: string) => {
 setDarkStore(storeId);
 setDeliveryZone("");
 setDeliveryZoneLabel("");
 setDeliveryPartner("");
 setPartners([]);
 if (!storeId) return;
 setLoadingZone(true);
 try {
 const zone = await fetchZoneForStore(storeId);
 if (zone) {
 setDeliveryZone(zone.id);
 setDeliveryZoneLabel(zone.label);
 setLoadingPartners(true);
 const p = await fetchDeliveryPartners(zone.id);
 setPartners(p);
 setLoadingPartners(false);
 }
 } catch (e) {
 console.error(e);
 } finally {
 setLoadingZone(false);
 }
 },
 []
 );

 const isValid =
 orderNumber.trim() &&
 darkStore &&
 deliveryZone &&
 deliveryPartner &&
 complaintType &&
 shortDesc.trim() &&
 description.trim();

 const doSubmit = useCallback(async () => {
 if (!isValid || submitting) return;
 setSubmitting(true);
 setError("");
 try {
 const result = await submitComplaint({
 order_number: orderNumber.trim(),
 order_value: orderValue || undefined,
 dark_store: darkStore,
 delivery_zone: deliveryZone,
 delivery_partner: deliveryPartner,
 complaint_type: complaintType,
 short_description: shortDesc.trim(),
 description: description.trim(),
 });
 const num =
 typeof result.number === "object"
 ? result.number.display_value
 : result.number;
 setSuccess({ number: num || result.sys_id, sys_id: result.sys_id });
 } catch (err: any) {
 setError(err.message || "An unexpected error occurred.");
 } finally {
 setSubmitting(false);
 }
 }, [
 isValid,
 submitting,
 orderNumber,
 orderValue,
 darkStore,
 deliveryZone,
 deliveryPartner,
 complaintType,
 shortDesc,
 description,
 ]);

 const handleFormSubmit = (e: React.FormEvent) => {
 e.preventDefault();
 doSubmit();
 };

 if (success) {
 return (
 <div className="cf-page">
 <div className="cf-container">
 <div className="cf-success">
 <div className="cf-success__icon" aria-hidden="true">&#10004;</div>
 <h1 className="cf-success__title">Complaint Submitted</h1>
 <p className="cf-success__desc">
 Your complaint has been received and assigned number:
 </p>
 <div className="cf-success__number">{success.number}</div>
 <p className="cf-success__info">
 Our team will review your complaint and get back to you shortly.
 </p>
 <div className="cf-success__actions">
 <button
 type="button"
 className="cf-submit-btn cf-submit-btn--secondary"
 onClick={() => window.location.reload()}
 >
 File Another Complaint
 </button>
 </div>
 </div>
 </div>
 </div>
 );
 }

 return (
 <div className="cf-page">
 <div className="cf-container">
 <header className="cf-header">
 <h1 className="cf-header__title">File a Complaint</h1>
 <p className="cf-header__subtitle">
 Tell us what went wrong with your order
 </p>
 </header>

 <form className="cf-form" onSubmit={handleFormSubmit} noValidate>
 <section className="cf-section">
 <h2 className="cf-section__title">Order Information</h2>
 <div className="cf-grid">
 <div className="cf-field">
 <label className="cf-field__label" htmlFor="orderNumber">
 Order Number <span className="cf-field__req">*</span>
 </label>
 <input
 id="orderNumber"
 className="cf-input"
 type="text"
 placeholder="e.g. ORD-2024-78541"
 value={orderNumber}
 onChange={(e) => setOrderNumber(e.target.value)}
 required
 aria-required="true"
 />
 </div>
 <div className="cf-field">
 <label className="cf-field__label" htmlFor="orderValue">
 Order Value
 </label>
 <input
 id="orderValue"
 className="cf-input"
 type="number"
 placeholder="e.g. 450.00"
 min="0"
 step="0.01"
 value={orderValue}
 onChange={(e) => setOrderValue(e.target.value)}
 />
 </div>
 </div>
 <div className="cf-grid">
 <div className="cf-field">
 <label className="cf-field__label" htmlFor="darkStore">
 Dark Store <span className="cf-field__req">*</span>
 </label>
 <select
 id="darkStore"
 className="cf-select"
 value={darkStore}
 onChange={(e) => handleDarkStoreChange(e.target.value)}
 required
 aria-required="true"
 >
 <option value="">-- Select a store --</option>
 {darkStores.map((s) => (
 <option key={s.id} value={s.id}>
 {s.label}
 </option>
 ))}
 </select>
 </div>
 <div className="cf-field">
 <label className="cf-field__label" htmlFor="deliveryZone">
 Delivery Zone <span className="cf-field__req">*</span>
 </label>
 <div className="cf-readonly" id="deliveryZone" aria-live="polite">
 {loadingZone
 ? "Loading..."
 : deliveryZoneLabel || "Auto-populated from store"}
 </div>
 </div>
 </div>
 <div className="cf-field">
 <label className="cf-field__label" htmlFor="deliveryPartner">
 Delivery Partner <span className="cf-field__req">*</span>
 </label>
 <select
 id="deliveryPartner"
 className="cf-select"
 value={deliveryPartner}
 onChange={(e) => setDeliveryPartner(e.target.value)}
 disabled={!deliveryZone || loadingPartners}
 required
 aria-required="true"
 >
 <option value="">
 {loadingPartners
 ? "Loading partners..."
 : !deliveryZone
 ? "Select a store first"
 : "-- Select a partner --"}
 </option>
 {partners.map((p) => (
 <option key={p.id} value={p.id}>
 {p.label}
 </option>
 ))}
 </select>
 </div>
 </section>

 <section className="cf-section">
 <h2 className="cf-section__title">What Went Wrong?</h2>
 <div className="cf-field">
 <label className="cf-field__label" htmlFor="complaintType">
 Complaint Type <span className="cf-field__req">*</span>
 </label>
 <select
 id="complaintType"
 className="cf-select"
 value={complaintType}
 onChange={(e) => setComplaintType(e.target.value)}
 required
 aria-required="true"
 >
 <option value="">-- Select complaint type --</option>
 {COMPLAINT_TYPES.map((t) => (
 <option key={t.value} value={t.value}>
 {t.label}
 </option>
 ))}
 </select>
 </div>
 </section>

 <section className="cf-section">
 <h2 className="cf-section__title">Tell Us What Happened</h2>
 <div className="cf-field">
 <label className="cf-field__label" htmlFor="shortDesc">
 Short Description <span className="cf-field__req">*</span>
 </label>
 <input
 id="shortDesc"
 className="cf-input"
 type="text"
 placeholder="Brief summary of your complaint"
 value={shortDesc}
 onChange={(e) => setShortDesc(e.target.value)}
 maxLength={160}
 required
 aria-required="true"
 />
 <div className="cf-field__hint">
 {shortDesc.length}/160 characters
 </div>
 </div>
 <div className="cf-field">
 <label className="cf-field__label" htmlFor="description">
 Detailed Description <span className="cf-field__req">*</span>
 </label>
 <textarea
 id="description"
 className="cf-textarea"
 placeholder="Please provide as much detail as possible about what happened..."
 value={description}
 onChange={(e) => setDescription(e.target.value)}
 rows={5}
 maxLength={4000}
 required
 aria-required="true"
 />
 <div className="cf-field__hint">
 {description.length}/4000 characters
 </div>
 </div>
 </section>

 {error && (
 <div className="cf-alert cf-alert--critical" role="alert">
 <strong>Error:</strong> {error}
 </div>
 )}

 <div className="cf-actions">
 <button
 type="submit"
 className="cf-submit-btn"
